import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    likes = data[1:n+1]

    # Track for each photo: list of positions (1-indexed)
    photo_positions = {}
    for pos, photo in enumerate(likes, start=1):
        if photo not in photo_positions:
            photo_positions[photo] = []
        photo_positions[photo].append(pos)

    # Find the winner
    winner = None
    max_count = -1

    for photo, positions in photo_positions.items():
        count = len(positions)
        # The time it reached this count is the last position
        time_reached = positions[-1]

        if count > max_count or (count == max_count and time_reached < winner_time):
            max_count = count
            winner = photo
            winner_time = time_reached

    print(winner)

if __name__ == "__main__":
    solve()
"}

