import sys

def solve() -> None:
    # Read input
    s1 = sys.stdin.readline().strip()
    s2 = sys.stdin.readline().strip()

    # Check if it's impossible
    if any(char not in s1 for char in s2):
        print(-1)
        return

    # Get positions of each character in s1
    positions = {}
    for i, char in enumerate(s1):
        if char not in positions:
            positions[char] = []
        positions[char].append(i)

    # For each character in s2, find the required positions
    last_pos = -1

    for char in s2:
        idxs = positions[char]
        idx = None

        # Find the smallest position that comes after last_pos
        for pos in idxs:
            if pos > last_pos:
                idx = pos
                break

        if idx is None:
            # Try wrapping around to the next copy of s1
            idx = idxs[0]
            last_pos = idx
            num_copies = 1

        last_pos = idx
        num_copies = (last_pos + 1) // len(s1)
        if (last_pos + 1) % len(s1) != 0:
            num_copies += 1


    print(num_copies)

if __name__ == "__main__":
    solve()
