    val_indices = defaultdict(list)
    for i, val in enumerate(a):
        val_indices[val].append(i)

    ans = 0
    for val, indices in val_indices.items():
        m = len(indices)
        for i in range(m):
            for j in range(i + 1, m):
                # indices[i] < indices[j]
                ans += indices[i] * (n - indices[j] + 1)
    print(ans)
