def solve():
    import sys
    input = sys.stdin.read().split()
    data = iter(input)

    n = int(next(data))
    m = int(next(data))
    k = int(next(data))

    planets = []

    for _ in range(n):
        name = next(data)
        planet = []
        for _ in range(m):
            a = int(next(data))
            b = int(next(data))
            c = int(next(data))
            planet.append((a, b, c))
        planets.append(planet)

    max_profit = 0

    # Try all pairs of planets
    for buy_planet in range(n):
        for sell_planet in range(n):
            if buy_planet == sell_planet:
                continue

            # Calculate potential profit for each item type
            items = []
            for j in range(m):
                a, b, c = planets[buy_planet][j]
                sell_price = planets[sell_planet][j][1]
                buy_price = planets[buy_planet][j][0]
                profit_per_item = sell_price - buy_price

                if profit_per_item <= 0:
                    continue  # No profit, skip

                max_items = min(c, k)
                items.append((profit_per_item, max_items))

            # Bounded knapsack: max capacity k, items with max quantity
            dp = [-1] * (k + 1)
            dp[0] = 0

            for profit, max_take in items:
                for cap in range(k + 1):
                    if dp[cap] != -1:
                        for take in range(1, max_take + 1):
                            if cap + take <= k:
                                dp[cap + take] = max(dp[cap + take], dp[cap] + take * profit)

            max_profit = max(max_profit, max(dp))

    print(max_profit)

if __name__ == "__main__":
    solve()
"}

