def solve():
    MOD = 10**9 + 7
    n = int(input())

    # Calculate factorial
    fact = [1] * (n + 1)
    for i in range(1, n + 1):
        fact[i] = (fact[i-1] * i) % MOD

    # Formula: f(n) = n! - 2 * (n-1)! + 2 * (n-2)!
    # Handle modulo properly
    if n >= 3:
        result = (fact[n] - 2 * fact[n-1] + 2 * fact[n-2]) % MOD
        # Handle negative numbers
        if result < 0:
            result += MOD
    else:
        result = 0

    print(result)

