def longest_common_subsequence(s1, s2, virus):
    m, n = len(s1), len(s2)

    # DP table for LCS length
    dp = [[0] * (n + 1) for _ in range(m + 1)]
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if s1[i-1] == s2[j-1]:
                dp[i][j] = dp[i-1][j-1] + 1
            else:
                dp[i][j] = max(dp[i-1][j], dp[i][j-1])

    # Reconstruct LCS
    i, j = m, n
    lcs = []

    while i > 0 and j > 0:
        if s1[i-1] == s2[j-1]:
            lcs.append(s1[i-1])
            i -= 1
            j -= 1
        else:
            if dp[i-1][j] > dp[i][j-1]:
                i -= 1
            else:
                j -= 1

    lcs.reverse()

    # Check if this LCS contains the virus
    if virus not in ''.join(lcs):
        return ''.join(lcs)

    # Try other possible LCS reconstructions
    # We need to try all possible paths
    # Let me use a recursive approach to explore all possibilities

    def backtrack(i, j, current):
        if i == 0 and j == 0:
            return current

        if s1[i-1] == s2[j-1]:
            # Choose this character
            result = backtrack(i-1, j-1, current + s1[i-1])
            if virus not in result:
                return result
            # Try other paths (though there's only one path in this case)
            return backtrack(i-1, j, current) or backtrack(i, j-1, current)

        if dp[i-1][j] == dp[i][j]:
            # Try moving in s1
            result = backtrack(i-1, j, current)
            if virus not in result:
                return result

        if dp[i][j-1] == dp[i][j]:
            # Try moving in s2
            result = backtrack(i, j-1, current)
            if virus not in result:
                return result

        return None

    return backtrack(m, n, "")

