import sys

def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    c = list(map(int, data[1:1+n]))

    if n == 1:
        if c[0] == 1:
            print("YES")
        else:
            print("NO")
        return

    # Sort in decreasing order
    c.sort(reverse=True)

    # Check root condition
    if c[0] != n:
        print("NO")
        return

    # Check for at least two leaves
    if c[1] != 1:
        print("NO")
        return

    # Check internal nodes
    for i in range(2, n):
        if c[i] > 1:
            # This node must have at least two children
            # Check if we can find two children with subtree sizes summing to at least c[i] - 1
            if c[-2] + c[-1] < c[i] - 1:
                print("NO")
                return
            # Remove the two smallest children and add the parent
            c = c[:-2] + [c[i]]

    print("YES")

if __name__ == "__main__":
    solve()
