import math
from sys import stdin

def factorial(n):
    return math.factorial(n)

def permutation_to_index(p):
    """Convert permutation to its lexicographical order index"""
    n = len(p)
    index = 0
    used = [False] * n

    for i in range(n):
        count = 0
        for num in range(n):
            if not used[num] and num < p[i]:
                count += 1
        index += count * factorial(n - i - 1)
        used[p[i]] = True

    return index

def index_to_permutation(index, n):
    """Convert lexicographical order index to permutation"""
    perm = [0] * n
    used = [False] * n
    idx = index

    for i in range(n):
        for num in range(n):
            if not used[num]:
                # Calculate how many permutations would be skipped if we place this number
                count = 0
                for n2 in range(n):
                    if not used[n2] and n2 < num:
                        count += 1
                if idx >= count * factorial(n - i - 1):
                    idx -= count * factorial(n - i - 1)
                else:
                    perm[i] = num
                    used[num] = True
                    break

    return perm

def main():
    data = stdin.read().split()
    if not data:
        return

    n = int(data[0])
    p = list(map(int, data[1:n+1]))
    q = list(map(int, data[n+1:2*n+1]))

    idx_p = permutation_to_index(p)
    idx_q = permutation_to_index(q)

    result_idx = (idx_p + idx_q) % factorial(n)  # Ensure we stay within bounds

    result = index_to_permutation(result_idx, n)

    print(' '.join(map(str, result)))

if __name__ == "__main__":
    main()
"}

