def gcd(x, y):
    """Compute greatest common divisor using Euclidean algorithm"""
    while y:
        x, y = y, x % y
    return x

def factorize(n):
    """Return prime factorization of n as a dictionary"""
    factors = {}
    i = 2
    while i * i <= n:
        while n % i == 0:
            factors[i] = factors.get(i, 0) + 1
            n //= i
        i += 1
    if n > 1:
        factors[n] = factors.get(n, 0) + 1
    return factors

# Read input
n, m = map(int, input().split())
numerator_list = list(map(int, input().split()))
denominator_list = list(map(int, input().split()))

# Combine factors for numerator
numerator_factors = {}
for num in numerator_list:
    factors = factorize(num)
    for p, cnt in factors.items():
        numerator_factors[p] = numerator_factors.get(p, 0) + cnt

# Combine factors for denominator
denominator_factors = {}
for den in denominator_list:
    factors = factorize(den)
    for p, cnt in factors.items():
        denominator_factors[p] = denominator_factors.get(p, 0) + cnt

# Compute GCD factors (common prime factors with minimum exponent)
gcd_factors = {}
for p in numerator_factors:
    if p in denominator_factors:
        gcd_factors[p] = min(numerator_factors[p], denominator_factors[p])

# Build output for numerator (after reducing)
numerator_output = []
for p in numerator_factors:
    if p in gcd_factors:
        cnt = numerator_factors[p] - gcd_factors[p]
        if cnt > 0:
            numerator_output.append(p)
            numerator_output.extend([p] * (cnt - 1))
    else:
        numerator_output.append(p)
        numerator_output.extend([p] * (numerator_factors[p] - 1))

# Build output for denominator (after reducing)
denominator_output = []
for p in denominator_factors:
    if p in gcd_factors:
        cnt = denominator_factors[p] - gcd_factors[p]
        if cnt > 0:
            denominator_output.append(p)
            denominator_output.extend([p] * (cnt - 1))
    else:
        denominator_output.append(p)
        denominator_output.extend([p] * (denominator_factors[p] - 1))

# Print output
