import sys

def solve():
    MOD = 10**9 + 7
    n = int(sys.stdin.readline())
    s = sys.stdin.readline().strip()

    # dp[i] = dictionary: {last_number: count}
    dp = [{} for _ in range(n+1)]

    # Base case: empty string
    dp[0] = {"": 1}  # 1 way to split empty string (no numbers)

    for i in range(1, n+1):
        for j in range(i):
            # Check if the number from j+1 to i is valid
            # No leading zeros
            if s[j] == '0':
                continue
            num = s[j:i]

            # Now check all ways to split the first j digits
            # and see if the last number in that split is less than num
            for last_str, cnt in dp[j].items():
                # For the empty string case (last_str = ""),
                # the number of ways is simply the count of splits ending at j
                # because the empty string represents no previous number,
                # so any valid number after it is fine
                if last_str == "":
                    dp[i][num] = (dp[i].get(num, 0) + cnt) % MOD
                else:
                    # Compare lexicographically
                    if last_str < num:
                        dp[i][num] = (dp[i].get(num, 0) + cnt) % MOD

    # Sum all ways to split the entire string (last number can be any valid ending)
    result = 0
    for cnt in dp[n].values():
        result = (result + cnt) % MOD

    print(result)

if __name__ == "__main__":
    solve()
