import sys

def solve():
    MOD = 10**9 + 7
    n = int(sys.stdin.readline())
    s = sys.stdin.readline().strip()

    # dp[i] = dictionary: {last_number: count}
    dp = [{} for _ in range(n + 1)]

    # Base case: empty string
    dp[0] = {"": 1}

    for i in range(1, n + 1):
        for j in range(i):
            # Check if the number from j+1 to i is valid (no leading zeros)
            if s[j] == '0':
                continue
            num_str = s[j:i]

            # Now consider all ways to split the first j digits
            for last_str, count in dp[j].items():
                if last_str == "":
                    # No previous number, so any valid num is fine
                    dp[i][num_str] = (dp[i].get(num_str, 0) + count) % MOD
                else:
                    # Compare lexicographically to ensure strictly increasing
                    if last_str < num_str:
                        dp[i][num_str] = (dp[i].get(num_str, 0) + count) % MOD

    # Sum all ways to split the entire string
    total = sum(dp[n].values()) % MOD
    print(total)

if __name__ == "__main__":
    solve()

