def solve():
    n, m = map(int, input().split())

    # Build the graph
    graph = [[] for _ in range(n)]
    for i in range(n):
        parts = list(map(int, input().split()))
        c = parts[0]
        neighbors = parts[1:1+c]
        graph[i] = neighbors

    s = int(input()) - 1  # Convert to 0-indexed

    # We'll use DFS with memoization
    # memo[0][v] = True if Petya wins from v on Petya's turn
    # memo[1][v] = True if Petya wins from v on Vasya's turn
    memo = [[None] * n for _ in range(2)]

    def dfs(v, turn):
        # Base case: terminal node
        if len(graph[v]) == 0:
            if turn == 0:  # Petya's turn, no move possible, Petya loses
                return False
            else:  # Vasya's turn, no move possible, Petya wins
                return True

        # Check memoization
        if memo[turn][v] is not None:
            return memo[turn][v]

        if turn == 0:  # Petya's turn
            # Petya wins if there exists a move to u where Vasya loses
            for u in graph[v]:
                if not dfs(u, 1):
                    memo[turn][v] = True
                    return True
            # If all moves lead to Vasya winning, Petya loses
            memo[turn][v] = False
            return False
        else:  # Vasya's turn
            # Petya wins if for all moves to u, Petya wins from u
            for u in graph[v]:
                if not dfs(u, 0):
                    memo[turn][v] = False
                    return False
            # If all moves lead to Petya winning, Petya wins
            memo[turn][v] = True
            return True

    result = dfs(s, 0)

    if result:
        print("Win")
    else:
        # Check if there's a cycle (draw)
        # We need to check if we can reach a cycle
        visited = [False] * n
        path = []

        def has_cycle(v, turn):
            if visited[v]:
                # If we've already visited this vertex and it's in the current path,
                # we've found a cycle
                if v in path:
                    return True
                return False
            visited[v] = True
            path.append(v)

            if turn == 0:
                for u in graph[v]:
                    if has_cycle(u, 1):
                        return True
            else:
                for u in graph[v]:
                    if has_cycle(u, 0):
                        return True

            path.pop()
            return False

        if has_cycle(s, 0):
            print("Draw")
        else:
            print("Lose")

