    # and that would cause a conflict
    option1_count = {}
    option2_count = {}

    for team, hometown, opt1, opt2 in clubs:
        option1_count[opt1] = option1_count.get(opt1, 0) + 1
        option2_count[opt2] = option2_count.get(opt2, 0) + 1

    # First pass: try to assign option1 where possible
    result = []

    for team, hometown, opt1, opt2 in clubs:
        # If option1 is unique, we can use it
        if option1_count[opt1] == 1:
            result.append(opt1)
            # Remove all references to this option1
            for other_team, other_hometown, other_opt1, other_opt2 in clubs:
                if other_opt1 == opt1:
                    option1_count[other_opt1] = 0
        else:
            # Try to use option2
            if option2_count[opt2] == 1:
                result.append(opt2)
                # Remove all references to this option2
                for other_team, other_hometown, other_opt1, other_opt2 in clubs:
