n, q = map(int, input().split())
size = 1 << n
a = list(map(int, input().split()))

def update_tree(pos, value):
    while pos <= size:
        tree[pos] += value
        pos += pos & -pos

def query_tree(r):
    res = 0
    while r > 0:
        res += tree[r]
        r -= r & -r
    return res

def sum_range(l, r):
    return query_tree(r) - query_tree(l - 1)

# Build the initial Fenwick tree
tree = [0] * (size + 1)
for i in range(size):
    update_tree(i + 1, a[i])

# Track global operations
xor_mask = 0
bit_swap = [0] * (n + 1)  # bit_swap[k] = 1 if we need to swap bits k and k+1

def apply_operation(idx, mask):
    # Apply XOR and bit swaps to a single index
    idx ^= mask
    for k in range(n):
        if bit_swap[k]:
            bit = (idx >> k) & 1
            if bit:
                idx ^= (1 << k)
                idx ^= (1 << (k + 1))
    return idx

def get_original_index(x):
    # Find original array index for position x after operations
    idx = x
    idx ^= xor_mask
    for k in range(n):
        if bit_swap[k]:
            bit = (idx >> k) & 1
            if bit:
                idx ^= (1 << k)
                idx ^= (1 << (k + 1))
    return idx

def get_mapped_index(x):
    # Find mapped position for original array index x
    idx = x
    for k in range(n):
        if bit_swap[k]:
            bit = (idx >> k) & 1
            if bit:
                idx ^= (1 << k)
                idx ^= (1 << (k + 1))
    idx ^= xor_mask
    return idx

for _ in range(q):
    parts = input().split()
    if parts[0] == '1':
        # Replace(x, k)
        x = int(parts[1])
        k = int(parts[2])
        # Find original array index
        orig_idx = get_original_index(x)
        # Remove old value
        update_tree(x, -a[orig_idx - 1])
        a[orig_idx - 1] = k
        # Add new value
        update_tree(x, k)
    elif parts[0] == '2':
        # Reverse(k): XOR with 2^k
        k = int(parts[1])
        xor_mask ^= (1 << k)
    elif parts[0] == '3':
        # Swap(k): Swap k-th bit with (k+1)-th bit
        k = int(parts[1])
        bit_swap[k] ^= 1
    elif parts[0] == '4':
        # Sum(l, r)
        l = int(parts[1])
        r = int(parts[2])
        result = 0
