from collections import defaultdict, deque

def solve():
    n, m = map(int, input().split())

    # Build adjacency list
    graph = defaultdict(list)
    for i in range(1, n + 1):
        parts = list(map(int, input().split()))
        c = parts[0]
        if c > 0:
            graph[i] = parts[1:]

    s = int(input())

    # Find terminal nodes (no outgoing edges)
    terminal = []
    for i in range(1, n + 1):
        if i not in graph:
            terminal.append(i)

    # Perform topological sort from terminal nodes
    # We'll use a distance array to store the minimum number of moves to reach a terminal
    distance = [float('inf')] * (n + 1)
    for node in terminal:
        distance[node] = 0

    # Use BFS to propagate distances
    queue = deque(terminal)
    while queue:
        node = queue.popleft()
        for neighbor in graph[node]:
            if distance[neighbor] > distance[node] + 1:
                distance[neighbor] = distance[node] + 1
                queue.append(neighbor)

    # Determine if we can win or draw
    if distance[s] == float('inf'):
        print("Draw")
    elif distance[s] % 2 == 0:
        print("Win")
        # Reconstruct the path
        path = []
        current = s
        for _ in range(distance[s] + 1):
            path.append(current)
            current = next(iter(graph[current])) if current in graph else None
        print(' '.join(map(str, path)))
    else:
        print("Lose")

solve()
