def is_valid(grid, rows, cols, pos, turn):
    """Check if a position is valid (not occupied by a train)"""
    train_positions = []

    # Find all train positions at turn t
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] != '.' and grid[r][c] != 's':
                # This is a train, track its initial position
                train_positions.append((r, c))

    # Check each train
    for train_r, train_c in train_positions:
        # After turn turns, the train has moved 2*turn left
        train_col = train_c - 2 * turn
        if train_col >= 0 and grid[train_r][train_col] == grid[train_r][train_c]:
            # The train is still on the grid and occupies this position
            if pos == (train_r, train_col):
                return False
    return True

def can_escape(grid, rows, cols, n):
    """Check if Philip can escape the tunnel"""
    # Find Philip's starting position
    start = None
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 's':
                start = (r, c)
                break
        if start:
            break

    if not start or start[1] != 0:
        return False  # Invalid starting position

    # BFS: (row, col, turn)
    from collections import deque
    visited = set()
    q = deque()
    q.append((start[0], start[1], 0))
    visited.add((start[0], start[1], 0))

    while q:
        r, c, t = q.popleft()

        # Check if we've reached the end
        if c == n - 1:
            return True

        # Move right
        if c < n - 1:
            if is_valid(grid, rows, cols, (r, c+1), t):
                if (r, c+1, t) not in visited:
                    visited.add((r, c+1, t))
                    q.append((r, c+1, t))

        # Move up (if possible)
        if r > 0:
            if is_valid(grid, rows, cols, (r-1, c), t):
                if (r-1, c, t) not in visited:
                    visited.add((r-1, c, t))
                    q.append((r-1, c, t))

        # Move down (if possible)
        if r < rows - 1:
            if is_valid(grid, rows, cols, (r+1, c), t):
                if (r+1, c, t) not in visited:
