def move_cost(from_c, to_c):
    if from_c == to_c:
        return 0
    if (from_c == 0 and to_c == 1) or (from_c == 1 and to_c == 0):
        return 1
    if (from_c == 0 and to_c == 2) or (from_c == 2 and to_c == 0):
        return 2
    if (from_c == 1 and to_c == 2) or (from_c == 2 and to_c == 1):
        return 1

def solve():
    n = int(input())
    computers = list(map(int, input().split()))
    dependencies = [[] for _ in range(n)]

    for i in range(n):
        parts = list(map(int, input().split()))
        k = parts[0]
        if k > 0:
            for j in parts[1:]:
                dependencies[i].append(j - 1)  # convert to 0-indexed

    # Topological sort using Kahn's algorithm
    in_degree = [0] * n
    for i in range(n):
        for j in dependencies[i]:
            in_degree[j] += 1

    queue = deque([i for i in range(n) if in_degree[i] == 0])
    top_order = []

    while queue:
        u = queue.popleft()
        top_order.append(u)
        for v in dependencies[u]:
            in_degree[v] -= 1
            if in_degree[v] == 0:
                queue.append(v)

    # DP: dp[i][c] = minimum time to complete all parts from top_order[0] to top_order[i], ending at computer c
    dp = [[float('inf')] * 3 for _ in range(n)]

    # Complete the first part
    for c in range(3):
        if c == 0:
            dp[0][c] = 0  # Start at computer 1 and complete on computer 1
        else:
            dp[0][c] = move_cost(0, computers[top_order[0]] - 1) + 1  # Start at computer 1, move to computer c, complete

    # Complete remaining parts
    for i in range(1, n):
        part = top_order[i]
        for c in range(3):
            dp[i][c] = move_cost(0, computers[part] - 1) + 1  # Start fresh and complete

            # Consider all ways to arrive at the required computer for this part
            for dc in range(3):
                dp[i][c] = min(dp[i][c], dp[i-1][dc] + move_cost(dc, computers[part] - 1) + 1)

    print(min(dp[n-1]))

solve()
