import sys
import math
from collections import Counter

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def gcd_of_list(nums):
    result = nums[0]
    for num in nums[1:]:
        result = gcd(result, num)
    return result

def factorize(n):
    factors = []
    i = 2
    while i * i <= n:
        while n % i == 0:
            factors.append(i)
            n //= i
        i += 1
    if n > 1:
        factors.append(n)
    return factors

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    # Parse input
    n = int(data[0])
    m = int(data[1])

    a = list(map(int, data[2:2+n]))
    b = list(map(int, data[2+n:2+n+m]))

    # Calculate GCD of the fraction
    gcd_fraction = gcd_of_list(a) if a else 1
    for num in b:
        gcd_fraction = gcd(gcd_fraction, num)

    # Factorize the GCD
    gcd_factors = factorize(gcd_fraction)

    # Count frequency of each factor
    gcd_factor_counts = Counter(gcd_factors)

    # Create new sets
    new_a = []
    new_b = []

    # Start with original sets
    for num in a:
        new_a.append(num)
    for num in b:
        new_b.append(num)

    # For each prime factor, remove it from both sets
    for prime in gcd_factor_counts:
        # Find the prime in numerator
        found_a = False
        for i in range(len(new_a) - 1, -1, -1):
            if new_a[i] % prime == 0:
                new_a[i] //= prime
                found_a = True
                break

        # Find the prime in denominator
        found_b = False
        for i in range(len(new_b) - 1, -1, -1):
            if new_b[i] % prime == 0:
                new_b[i] //= prime
                found_b = True
                break

        # If prime is only in numerator, put it in denominator
        if not found_b:
            for i in range(len(new_a) - 1, -1, -1):
                if new_a[i] % prime == 0:
                    new_a[i] //= prime
                    break
            for i in range(len(new_b) - 1, -1, -1):
                if new_b[i] % prime == 0:
                    new_b[i] *= prime
                    break
        # If prime is only in denominator, put it in numerator
        elif not found_a:
            for i in range(len(new_b) - 1, -1, -1):
                if new_b[i] % prime == 0:
                    new_b[i] //= prime
                    break
            for i in range(len(new_a) - 1, -1, -1):
                if new_a[i] % prime == 0:
                    new_a[i] *= prime
                    break

    # Output
    print(n, m)
    print(' '.join(map(str, new_a)))
    print(' '.join(map(str, new_b)))

solve()
