def to_base3(n):
    """Convert n to base 3 as a string, right to left."""
    if n == 0:
        return "0"
    res = []
    while n > 0:
        res.append(str(n % 3))
        n //= 3
    return ".join(reversed(res))

def from_base3(s):
    """Convert base 3 string to integer."""
    return int(s, 3)

def find_next_good_number(n):
    """Find the smallest good number >= n."""
    # Convert to base 3
    base3 = to_base3(n)

    # If there are no 2s, n is already good
    if '2' not in base3:
        return n

    # Find the leftmost 2
    leftmost_2_index = base3.index('2')

