import itertools

def solve():
    n, m, k = map(int, input().split())

    # For each row, find all possible sums with up to floor(m/2) elements
    row_options = []
    for _ in range(n):
        row = list(map(int, input().split()))

        # Use DP to track possible remainders for each possible number of elements chosen
        # dp[j][r] = max sum choosing exactly j elements with remainder r
        max_choose = m // 2
        dp = [[-float('inf')] * k for _ in range(max_choose + 1)]
        dp[0][0] = 0

        for num, val in enumerate(row):
            # We can choose to include or exclude this element
            for j in range(max_choose, -1, -1):
                for r in range(k):
                    if dp[j][r] != -float('inf') and dp[j][r] + val <= dp[j+1][(r + val) % k]:
                        dp[j+1][(r + val) % k] = dp[j][r] + val

        # Collect all possible remainders with max sums
        sums = {}
        for j in range(max_choose + 1):
            for r in range(k):
                if dp[j][r] != -float('inf'):
                    sums[r] = max(sums.get(r, -float('inf')), dp[j][r])

        row_options.append(sums)

    # DP to combine rows
    dp = [{} for _ in range(n + 1)]
    dp[0][0] = 0

    for i in range(1, n + 1):
        row_sums = row_options[i - 1]

        # Combine with previous dp state
        for prev_r, prev_sum in dp[i - 1].items():
            for curr_r, curr_val in row_sums.items():
                new_r = (prev_r + curr_r) % k
                new_sum = prev_sum + curr_val
                dp[i][new_r] = max(dp[i].get(new_r, -float('inf')), new_sum)

    # Find max sum with remainder 0
    print(dp[n].get(0, 0))

