    dp = [[0] * (max_diff + 1) for _ in range(n + 1)]
    dp[0][0] = 1

    # Precompute combinations C(n, k)
    C = [[0] * (max_diff + 1) for _ in range(n + 1)]
    for n_comb in range(n + 1):
