def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    p = int(data[0])
    d = int(data[1])

    # Try up to 18 digits (since p <= 10^18)
    best_price = p

    for k in range(1, 19):
        # We want the price to end with k nines
        # The largest number <= p ending with k nines is:
        # p - (p % (10^k)) + (10^k - 1) if that's <= p
        power = 10 ** k
        target = p - (p % power) + (power - 1)

        # If target is valid, update
        if target <= p and target >= p - d:
            best_price = target
        elif target > p:
            # Try the next lower number that ends with k nines
            best_price = p - (p % power) - 1 + (power - 1)
            if best_price >= p - d:
                best_price = p - (p % power) - 1 + (power - 1)
            else:
                best_price = p - (p % power) - 1 + (power - 1)

    print(best_price)

