def solve():
    x, y = map(int, sys.stdin.readline().split())

    if x == 0 and y == 0:
        print(0)
        return

    # Start at (0, 0)
    cx, cy = 0, 0
    turns = 0
    n = 1  # Length of current segment

    while True:
        # Move right
        if cx == x and cy == y:
            print(turns)
            return
        for i in range(n):
            cx += 1
            if cx == x and cy == y:
                print(turns)
                return
        turns += 0  # No turn after first segment

        # Move up
        if cx == x and cy == y:
            print(turns)
            return
        for i in range(n):
            cy += 1
            if cx == x and cy == y:
                print(turns)
                return
        turns += 1  # Turn after second segment

        # Move left
        if cx == x and cy == y:
            print(turns)
            return
        for i in range(n):
            cx -= 1
            if cx == x and cy == y:
                print(turns)
                return
        turns += 1  # Turn after third segment

        # Move down
        if cx == x and cy == y:
            print(turns)
            return
        for i in range(n):
            cy -= 1
            if cx == x and cy == y:
                print(turns)
                return
        turns += 1  # Turn after fourth segment

        n += 1

if __name__ == "__main__":
    solve()
