import sys

def longest_common_subsequence(s1, s2, virus):
    # Standard LCS DP to find length
    n, m = len(s1), len(s2)
    dp = [[0] * (m + 1) for _ in range(n + 1)]

    # Fill DP table
    for i in range(n):
        for j in range(m):
            if s1[i] == s2[j]:
                dp[i + 1][j + 1] = dp[i][j] + 1
            else:
                dp[i + 1][j + 1] = max(dp[i + 1][j], dp[i][j + 1])

    # Reconstruct one LCS
    i, j = n, m
    lcs = []
    while i > 0 and j > 0:
        if s1[i - 1] == s2[j - 1]:
            lcs.append(s1[i - 1])
            i -= 1
            j -= 1
        else:
            if dp[i][j] == dp[i - 1][j]:
                i -= 1
            else:
                j -= 1

    lcs.reverse()

    # Check if lcs contains virus as substring
    if virus not in ''.join(lcs):
        return ''.join(lcs)

    # If lcs contains virus, try different paths
    # We need to find another LCS that avoids virus
    # Let's try a different reconstruction

    # Reset and try different path
    i, j = n, m
    lcs2 = []
    while i > 0 and j > 0:
        if s1[i - 1] == s2[j - 1]:
            lcs2.append(s1[i - 1])
            i -= 1
            j -= 1
        else:
            # Try going up first
            if dp[i][j] == dp[i - 1][j]:
                i -= 1
            # Try going left first
            else:
                j -= 1

    lcs2.reverse()

    # Check if lcs2 contains virus
    if virus not in ''.join(lcs2):
        return ''.join(lcs2)

    # If both contain virus, no valid LCS
    return "0"

# Read input
s1 = input().strip()
s2 = input().strip()
virus = input().strip()

# Solve and print
result = longest_common_subsequence(s1, s2, virus)
print(result)
