            else:
                dp[i + 1][j + 1] = max(dp[i + 1][j], dp[i][j + 1])

    # Reconstruct LCS while avoiding virus
    i, j = n, m
    lcs = []
    virus_len = len(virus)

    # Check if a string contains virus as substring
    def contains_virus(s):
        return virus in s

    # Backtracking to find a valid LCS
    def find_lcs(i, j, current):
        # If we've reached the end of both strings, check if current is valid
        if i == 0 and j == 0:
            return current if not contains_virus(current) else None

        # If we've reached the end of one string, return current (can't add more)
        if i == 0:
            return current if not contains_virus(current) else None
        if j == 0:
            return current if not contains_virus(current) else None

        # Try not taking s1[i-1]
        result = find_lcs(i - 1, j, current)
        if result is not None:
            return result

        # Try not taking s2[j-1]
        result = find_lcs(i, j - 1, current)
        if result is not None:
            return result

