    elif from_c == 1 and to_c == 3:
        return 2
    elif from_c == 2 and to_c == 1:
        return 2
    elif from_c == 2 and to_c == 3:
        return 1
    elif from_c == 3 and to_c == 1:
        return 1
    elif from_c == 3 and to_c == 2:
        return 2
    else:
        return 0

def solve():
    n = int(input())
    computers = list(map(int, input().split()))

    # Build adjacency list
    graph = [[] for _ in range(n+1)]
    in_degree = [0] * (n+1)

    for i in range(1, n+1):
        parts = list(map(int, input().split()))
        k = parts[0]
        deps = parts[1:] if k > 0 else []
        graph[i] = deps
        for dep in deps:
            in_degree[i] += 1

    # Topological sort using Kahn's algorithm
    queue = []
    for i in range(1, n+1):
        if in_degree[i] == 0:
            queue.append(i)

    top_order = []
    while queue:
        u = queue.pop(0)
        top_order.append(u)
        for v in graph[u]:
            in_degree[v] -= 1
            if in_degree[v] == 0:
                queue.append(v)

    # DP: dp[i][c] = min time to complete all parts up to i, ending on computer c
    INF = float('inf')
    dp = [ [INF] * 4 for _ in range(n+1) ]  # 1-indexed parts

    # Initialize: start at computer 1 (we can choose any starting computer)
    dp[0][1] = 0

    for i in range(1, n+1):
        # If we end on computer computers[i-1], we can come from any previous computer
        for prev_c in range(1, 4):
            if dp[i-1][prev_c] != INF:
                move = move_time(prev_c, computers[i-1])
                dp[i][computers[i-1]] = min(
                    dp[i][computers[i-1]],
                    dp[i-1][prev_c] + move + 1
                )

    # Answer is the minimum time among all ending computers
    print(min(dp[n][1], dp[n][2], dp[n][3]))

solve()
