                  (1, -1),  (1, 0), (1, 1)]

    for i in range(n):
        for j in range(m):
            cell = grid[i][j]

            if cell.isdigit() and 1 <= int(cell) <= 8:
                # Count bomb neighbors
                bomb_count = 0
                for dx, dy in directions:
                    ni, nj = i + dx, j + dy
                    if 0 <= ni < n and 0 <= nj < m:
                        if grid[ni][nj] == '*':
                            bomb_count += 1

                if bomb_count != int(cell):
                    return False
            elif cell == '.':
                # Check if any neighbor is a bomb
                for dx, dy in directions:
