# Check if a position is valid (within bounds)
def is_valid(i, j):
    return 0 <= i < n and 0 <= j < m

# Count bombs in 8 neighbors
def count_bombs(i, j):
    bomb_count = 0
    for di in [-1, 0, 1]:
        for dj in [-1, 0, 1]:
            ni, nj = i + di, j + dj
            if is_valid(ni, nj) and grid[ni][nj] == '*':
                bomb_count += 1
    return bomb_count

valid = True
for i in range(n):
    for j in range(m):
        cell = grid[i][j]
        if cell.isdigit():
            # Digit cell: should have exactly cell value bombs
            bomb_count = count_bombs(i, j)
            if bomb_count != int(cell):
                valid = False
                break
        elif cell == '.':
            # Empty cell: should have 0 bombs
            bomb_count = count_bombs(i, j)
            if bomb_count != 0:
                valid = False
                break
    if not valid:
        break

print("YES" if valid else "NO")

