def solve():
    s1 = sys.stdin.readline().strip()
    s2 = sys.stdin.readline().strip()

    # Check if all characters in s2 exist in s1
    char_positions = {}
    for i, c in enumerate(s1):
        if c not in char_positions:
            char_positions[c] = []
        char_positions[c].append(i)

    # Check if s2 can be formed
    for c in s2:
        if c not in char_positions:
            print(-1)
            return

    # Find minimum number of copies needed
    current_pos = -1  # Position in the current copy of s1
    copy_count = 1

    for c in s2:
        # Find the smallest position in s1 that is > current_pos
        positions = char_positions[c]
        found = -1
        for pos in positions:
            if pos > current_pos:
                found = pos
                break

        if found == -1:
            # Need to wrap to the next copy
            copy_count += 1
            found = positions[0]

        current_pos = found

    print(copy_count)

if __name__ == "__main__":
    solve()
