    # For each cell, try to place a star of maximum size
    for i in range(n):
        for j in range(m):
            if grid[i][j] == '*':
                # Find the maximum possible size
                max_size = min(i, j, n - 1 - i, m - 1 - j)
                # Check if a star of size max_size can be placed
                can_place = True
                for s in range(1, max_size + 1):
                    # Check if placing a star of size s covers only '*' cells
                    # The star covers: (i-s, j), (i, j-s), (i, j), (i, j+s), (i+s, j)
                    if grid[i-s][j] != '*' or grid[i][j-s] != '*' or grid[i][j+s] != '*' or grid[i+s][j] != '*':
                        can_place = False
                        break

                if can_place:
                    stars.append((i+1, j+1, max_size))  # Convert to 1-indexed

    # Check if all '*' cells are covered
    covered = [[False] * m for _ in range(n)]
    for x, y, s in stars:
        for dx in range(-s, s + 1):
            for dy in range(-s, s + 1):
                if abs(dx) + abs(dy) == s or abs(dx) + abs(dy) == 0:
                    nx, ny = x + dx - 1, y + dy - 1  # Convert back to 0-indexed
                    if 0 <= nx < n and 0 <= ny < m:
