y = list(map(int, input().split()))

# Check if we can form two parallel lines
# Try all pairs of points to find potential lines
for i in range(n):
    for j in range(i + 1, n):
        # Try to find a line through points i and j
        line1 = set([i, j])
        for k in range(n):
            if k in line1:
                continue
            # Check if point k can be on the same line
            # Slope between i and j should equal slope between j and k
            if (y[k] - y[j]) * (j - i) == (y[j] - y[i]) * (k - j):
                line1.add(k)

        # Now check if the remaining points can form another line that's parallel
        remaining = []
        for l in range(n):
            if l not in line1:
                remaining.append(l)

        if len(remaining) < 1:
            continue

        # Find the slope of the first line
        if len(line1) > 1:
            if line1.pop() == line1.pop():
                # Vertical line, slope is undefined
                vertical = True
            else:
                vertical = False
                slope1 = (y[line1.pop()] - y[line1.pop()]) / (line1.pop() - line1.pop())
        else:
            vertical = True

        # Check if the remaining points can form a parallel line
        can_form_second = True
        if vertical:
            # Check if all remaining points have the same x-coordinate (vertical line)
            x = list(line1)[0]
            for point in remaining:
                if point != x:
                    can_form_second = False
                    break
        else:
            # Check if the slope between the first two points of the second line matches
            if len(remaining) < 2:
                can_form_second = False
            else:
                line2 = set([remaining[0], remaining[1]])
                slope2 = (y[line2.pop()] - y[line2.pop()]) / (line2.pop() - line2.pop())
                if slope2 != slope1:
                    can_form_second = False
                else:
                    # Check if all remaining points can be on this line
                    for m in range(len(remaining)):
                        if m < 2:
