import sys

def longest_common_subsequence_without_virus(s1, s2, virus):
    """Find the longest common subsequence of s1 and s2 that doesn't contain virus as a substring."""

    # Build DP table for LCS length
    n, m = len(s1), len(s2)
    dp = [[0] * (m + 1) for _ in range(n + 1)]

    for i in range(n):
        for j in range(m):
            if s1[i] == s2[j]:
                dp[i+1][j+1] = dp[i][j] + 1
            else:
                dp[i+1][j+1] = max(dp[i+1][j], dp[i][j+1])

    # Now find the actual LCS characters
    def backtrack(i, j):
        """Backtrack through DP table to find one LCS."""
        if i == 0 or j == 0:
            return []

        if s1[i-1] == s2[j-1]:
            return backtrack(i-1, j-1) + [s1[i-1]]
        elif dp[i][j] == dp[i-1][j]:
            return backtrack(i-1, j)
        else:
            return backtrack(i, j-1)

    lcs_chars = backtrack(n, m)

    # Check if virus is a substring of LCS
    if virus not in ''.join(lcs_chars):
        return ''.join(lcs_chars)

    # If virus is a substring, try different LCS combinations
    # This part is more complex... let me think.

    # For small strings, we can try all combinations
    # This is still going to be exponential in the worst case

    # Instead, let's use a recursive backtracking approach to find the longest valid subsequence

    best = ""

    def find_lcs(i, j, current):
        """Find longest common subsequence from s1[i:] and s2[j:], adding to current."""
        nonlocal best

        if virus in current:
            return

        if i >= n or j >= m:
            if len(current) > len(best):
                best = current
            return

        # Option 1: don't take s1[i]
        find_lcs(i+1, j, current)

        # Option 2: don't take s2[j]
        find_lcs(i, j+1, current)

        # Option 3: take s1[i] if it matches s2[j]
        if s1[i] == s2[j]:
            find_lcs(i+1, j+1, current + s1[i])

    find_lcs(0, 0, "")

    return best if best else "0"

