def is_parallel_line(n, y):

    # Try all pairs of points as potential pairs on different lines
    for i in range(n):
        for j in range(i + 1, n):
            yi, yj = y[i], y[j]
            # These two points are on different lines

            # Calculate the slope between them
            # Avoid division by multiplying through

            # For any point (x, y) to be on one of these lines:
            # (y - yi) * (i - j) == (yi - yj) * (x - i)  or  (y - yj) * (i - j) == (yi - yj) * (x - j)

            # To check if all points satisfy one of these conditions
            line1_key = None
            line2_key = None

            for x in range(n):
                yx = y[x]

                # Check if this point could be on the same line as (i, yi)
                if (yx - yi) * (i - j) == (yi - yj) * (x - i):
                    if line1_key is None:
                        line1_key = (i, yi)
                    else:
                        # Check if the point lies on the same line as defined by line1_key
                        # Use same condition
                        if (yx - line1_key[1]) * (i - line1_key[0]) != (line1_key[1] - yj) * (x - line1_key[0]):
                            break

                # Check if this point could be on the same line as (j, yj)
                elif (yx - yj) * (i - j) == (yi - yj) * (x - j):
