def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    states = list(map(int, data[1:1+n]))

    # Find groups of consecutive unread letters (1s)
    groups = []
    start = -1

    for i in range(n):
        if states[i] == 1:
            if start == -1:
                start = i
        else:
            if start != -1:
                groups.append((start, i - 1))
                start = -1

    if start != -1:
        groups.append((start, n - 1))

