    # First group always needs to start from list
    first_start, first_end = groups[0]
    total += first_end - first_start + 1  # size of first group

    for i in range(1, len(groups)):
        prev_start, prev_end = groups[i-1]
        curr_start, curr_end = groups[i]

        # Check if adjacent
        if curr_start == prev_end + 1:
            # adjacent: just move from last of previous to first of current
            total += 1
        else:
            # separated: return to list (1) and go to first (1)
            total += 2

    print(total)

