    stripe_length = 1
    for i in range(1, n):
        if a[i] == first_val:
            stripe_length += 1
        else:
            break

    # Check if the pattern alternates correctly and all stripes have the same length
    current_val = first_val
    for i in range(stripe_length, n):
        if a[i] != (1 - current_val):
            # Pattern doesn't alternate correctly
            print("NO")
