        # Check if we're at the end of a stripe
        if i + 1 >= n or a[i + 1] != a[i]:
            # End of stripe, check if next stripe has same length
            if i + 1 >= n:
                # Last stripe
                return
            if stripe_length != 1:
                # Next stripe should have same length
                print("NO")
                return
            current_val = 1 - current_val

    print("YES")

if __name__ == "__main__":
