pos = []
for i in range(m):
    p = perms[i]
    pos.append([0] * (n + 1))  # 1-indexed
    for j in range(n):
        pos[i][p[j]] = j + 1  # positions are 1-indexed

# For each permutation, we'll track sequences
# dp[i][l] = maximum value for sequences of length l ending at position i
# that are common to all permutations so far.
dp = [{} for _ in range(n + 1)]

# Initialize for first permutation
for i in range(1, n + 1):
    dp[i][1] = i  # sequence of length 1 ending at position i

# Process remaining permutations
for i in range(2, n + 1):
    # For each possible length in dp[i-1]
    for l in dp[i-1]:
        # Try to extend the sequence
        # The value represents the last element of the sequence
        if l + 1 not in dp[i]:
            dp[i][l + 1] = dp[i-1][l] + 1
        else:
            dp[i][l + 1] = max(dp[i][l + 1], dp[i-1][l] + 1)

# Count all sequences
count = 0
for i in range(1, n + 1):
    for l in dp[i]:
        count += 1

print(count)
