        cards = parts[1:]
        piles.append(cards)

    # Use DP with memoization
    from functools import lru_cache

    # Convert piles to a tuple of tuples for hashing
    def to_key(piles):
        return tuple(tuple(pile) for pile in piles)

    @lru_cache(None)
    def game(piles_tuple):
        # Convert back to list for processing
        piles = [list(pile) for pile in piles_tuple]

        # Base case: all piles are empty
        if all(len(pile) == 0 for pile in piles):
            return (0, 0)  # (ciel_score, jiro_score)

        # Ciel's turn: maximize her score while minimizing Jiro's
        ciel_score = -float('inf')
        for i in range(len(piles)):
            if len(piles[i]) > 0:
                new_piles = list(piles)
                new_piles[i] = new_piles[i][1:]  # Take from top
                score = game(tuple(tuple(pile) for pile in new_piles))
                # Current move gives Ciel piles[i][0], and the rest of the game
                ciel_score = max(ciel_score, score[0] + piles[i][0] - score[1])

        # Jiro's turn: minimize Ciel's score while maximizing his own
        jiro_score = float('inf')
        for i in range(len(piles)):
            if len(piles[i]) > 0:
                new_piles = list(piles)
                new_piles[i] = new_piles[i][:-1]  # Take from bottom
                score = game(tuple(tuple(pile) for pile in new_piles))
                # Current move gives Jiro piles[i][-1], and the rest of the game
                jiro_score = min(jiro_score, score[0] - score[1] + piles[i][-1])

        return (ciel_score, jiro_score)

    result = game(tuple(tuple(pile) for pile in piles))
