import heapq

x1, y1 = map(int, input().split())
x2, y2 = map(int, input().split())
n = int(input())
s = input().strip()

# Precompute wind directions
wind = []
for ch in s:
    if ch == 'U':
        wind.append((0, 1))
    elif ch == 'D':
        wind.append((0, -1))
    elif ch == 'L':
        wind.append((-1, 0))
    elif ch == 'R':
        wind.append((1, 0))

def manhattan(pos):
    return abs(pos[0] - x2) + abs(pos[1] - y2)

def solve():
    start = (x1, y1, 0)
    end = (x2, y2)

    # Priority queue (days, x, y)
    heap = [(0, x1, y1, 0)]
    visited = set()
    visited.add((x1, y1))

    while heap:
        days, x, y, wind_idx = heapq.heappop(heap)

        # Check if we reached the target
        if (x, y) == (x2, y2):
            return days

        # Try all 5 moves
        for dx_ship, dy_ship in [(0, 0), (1, 0), (-1, 0), (0, 1), (0, -1)]:
            w_idx = (wind_idx + 1) % n
            wx, wy = wind[w_idx]
            nx, ny = x + wx + dx_ship, y + wy + dy_ship

            state = (nx, ny)

            if state not in visited:
                visited.add(state)
                heapq.heappush(heap, (days + 1, nx, ny, w_idx))

    return -1

print(solve())
