import sys

def solve():
    MOD = 998244353
    n, m = map(int, sys.stdin.readline().split())
    a = []
    for _ in range(n):
        a.append(list(map(int, sys.stdin.readline().split())))

    # Sort all positions by value descending
    positions = []
    for i in range(n):
        for j in range(m):
            positions.append((a[i][j], i, j))

    positions.sort(reverse=True)

    # Precompute positions for each value
    from collections import defaultdict
    value_pos = defaultdict(list)
    for val, i, j in positions:
        value_pos[val].append((i, j))

    # dp[i][j] = expected score from position (i, j)
    dp = [[0] * m for _ in range(n)]

    # cnt[i][j] = number of positions with value < a[i][j] that have already been processed
    cnt = [[0] * m for _ in range(n)]

    # sum_dp[i][j] = sum of (distance^2 + dp) for those positions
    sum_dp = [[0] * m for _ in range(n)]

    # Process positions in descending order of value
    for val_group in value_pos.values():
        val = val_group[0][0]  # All positions in this group have same value

        # Process all positions with this value
        # First, compute expected scores for all positions with this value
        # We need to know how many and sum of positions with smaller values

        # Actually, the number of positions with value < val is:
        # For each (i, j) with value v, it's the count of all positions with value < v

        # We can precompute a 2D prefix sum for value counts
        # But let's compute it for each position

        # For each position (i, j) in this group:
        k = 0
        for ni in range(n):
            for nj in range(m):
                if a[ni][nj] < val:
                    k += 1

        # Actually, I should use the precomputed list
        # Let's compute counts once per value
        value_counts = 0
        for ni in range(n):
            for nj in range(m):
                if a[ni][nj] < val:
                    value_counts += 1

        # For each position (i, j) in this group:
        for i, j in val_group:
            if value_counts == 0:
                # No positions with smaller value, score is 0
                dp[i][j] = 0
            else:
                # Sum of contributions from all positions with smaller value
                total = 0
                for ni in range(n):
                    for nj in range(m):
                        if a[ni][nj] < val:
                            dist = (i - ni) ** 2 + (j - nj) ** 2
                            total = (total + (dist + dp[ni][nj])) % MOD
                dp[i][j] = total * pow(value_counts, MOD - 2, MOD) % MOD

        # Now update cnt and sum_dp for all positions with value > val
        # Actually, we should do this incrementally
        # Let's just do it now for simplicity (not optimal but might pass)

        # For each position (i, j) in this group:
        for i, j in val_group:
            # Add this position to all positions with larger value
            for ni in range(n):
                for nj in range(m):
                    if a[ni][nj] > val:
                        cnt[ni][nj] = (cnt[ni][nj] + 1) % MOD
                        dist = (ni - i) ** 2 + (nj - j) ** 2
                        sum_dp[ni][nj] = (sum_dp[ni][nj] + (dist + dp[i][j])) % MOD

    # Start at (r-1, c-1)
    r, c = map(int, sys.stdin.readline().split())
    print(dp[r-1][c-1])

if __name__ == "__main__":
    solve()
