def is_valid_subtree(ci):
    """Check if a subtree with ci nodes can exist given the constraints."""
    # Base case: leaf node (no children)
    if ci == 1:
        return True

    # ci > 1: node has at least two children
    # We need to partition ci-1 into at least two parts (for children)
    # Each part must be at least 1 (child itself) and the sum of all parts = ci-1

    # Try all possible partitions of ci-1 into at least two parts
    # This is equivalent to checking all possible ways to distribute ci-1 nodes among at least two children

    # Since ci <= 24, this is feasible with backtracking

    # We'll use a recursive backtracking approach

    def backtrack(remaining, children_count, current_partition):
        # Base case: we've distributed all remaining nodes
        if remaining == 0:
            # We need at least two children
            if children_count >= 2:
                # Check if all parts are valid subtree sizes
                for size in current_partition:
                    if not is_valid_subtree(size):
                        return False
                return True
            return False

        # Try to add a child with 1 node (leaf)
        if backtrack(remaining - 1, children_count + 1, current_partition + [1]):
            return True

        # Try to add a child with 2 or more nodes (internal node)
        for size in range(2, remaining + 1):
            if backtrack(remaining - size, children_count + 1, current_partition + [size]):
                return True

        return False

    return backtrack(ci - 1, 0, [])

def solve():
    n = int(input())
    c = list(map(int, input().split()))

    # For each node, check if its subtree size is valid
    for ci in c:
        if not is_valid_subtree(ci):
            print("NO")
            return

    print("YES")

solve()
