{"code": "
def is_palindrome(s, l, r):
    while l < r:
        if s[l] != s[r]:
            return False
        l += 1
        r -= 1
    return True

n = len(s)
# dp[l][r][k] = True if substring s[l:r+1] is a k-palindrome
# We'll use a 2D array of sets for efficiency
k_max = n
# dp[l][r] will store all k values for which the substring is k-palindrome
# We'll use a 2D array of dictionaries
from collections import defaultdict

dp = [[set() for _ in range(n)] for _ in range(n)]

# Base case: k=1
for l in range(n):
    for r in range(l, n):
        if is_palindrome(s, l, r):
            dp[l][r].add(1)

# For k > 1
for k in range(2, k_max + 1):
    for l in range(n):
        for r in range(l, n):
            # Get substring length
            length = r - l + 1
            half_len = length // 2

            # Get left and right half boundaries
            left_r = l + half_len - 1
            right_l = r - half_len + 1

            # Check if both halves are (k-1)-palindromes and if they're equal
            if dp[l][left_r] and dp[right_l][r] and dp[l][left_r].intersection(dp[right_l][r]) and s[l:right_l] == s[right_l+1:r+1]:
                dp[l][r].add(k)

# Count for each k
result = [0] * n
for k in range(1, n + 1):
    count = 0
    for l in range(n):
        for r in range(l, n):
            if k in dp[l][r]:
                count += 1
    result[k-1] = count

print(' '.join(map(str, result)))
