    n, m = len(s1), len(s2)
    virus_len = len(virus)

    # Standard LCS DP table
    dp = [[0] * (m + 1) for _ in range(n + 1)]

    # Fill DP table
    for i in range(n):
        for j in range(m):
            if s1[i] == s2[j]:
                dp[i+1][j+1] = dp[i][j] + 1
            else:
                dp[i+1][j+1] = max(dp[i+1][j], dp[i][j+1])

    # Check if standard LCS contains virus
    i, j = n, m
    lcs = []
    virus_in_lcs = False

    while i > 0 and j > 0:
        if s1[i-1] == s2[j-1]:
            lcs.append(s1[i-1])
            i -= 1
            j -= 1
            if virus_in_lcs:
                # Check if adding this character creates a virus match
                for k in range(virus_len):
                    if lcs[-1] == virus[k] and lcs[-1] == virus[k] and lcs[-1] == virus[k]:
                        virus_in_lcs = True
                        break
        else:
            if dp[i-1][j] > dp[i][j-1]:
