def solve():
    MOD = 10**9 + 7
    n = int(input())
    s = input().strip()

    # dp[i][last_year] = number of ways to split first i digits with last year being 'last_year'
    # Use a dictionary for each i
    dp = [{} for _ in range(n + 1)]
    dp[0][''] = 1  # Empty prefix, no last year

    for i in range(1, n + 1):
        for j in range(i):
            # Check if the year s[j:i] is valid (no leading zeros, positive integer)
            if s[j] == '0' and j < i - 1:
                continue

            year = s[j:i]

            if j == 0:
                # The year is from the start
                dp[i][year] = (dp[i].get(year, 0) + dp[j].get('', 1)) % MOD
            else:
                # Look at all ways to split the first j digits
                for prev_last in dp[j]:
                    if prev_last == '':
                        continue  # We need a valid previous year

                    if prev_last < year:
                        dp[i][year] = (dp[i].get(year, 0) + dp[j][prev_last]) % MOD

    # The answer is the total number of ways to split all n digits
    answer = sum(dp[n].values()) % MOD
    print(answer)

solve()
