    a = list(map(int, input().split()))
    total = 0

    # Map from value to list of indices
    value_indices = {}
    for i in range(n):
        val = a[i]
        if val not in value_indices:
            value_indices[val] = []
        value_indices[val].append(i)

    # For each value, compute contribution of all pairs
    for indices in value_indices.values():
        m = len(indices)
        # Contribution of a pair (i, j) with i < j
        for j in range(m):
            for i in range(j):
                # Pair (i, j) has value a[indices[i]]
                # It appears in (indices[i] + 1) subsegments starting at or before indices[i]
                # And (n - indices[j]) subsegments ending at or after indices[j]
                total += (indices[i] + 1) * (n - indices[j])

    print(total)
