    """Apply the function f to x"""
    x += 1
    while x % 10 == 0:
        x //= 10
    return x

def count_reachable(n):
    """Count how many different numbers are reachable from n"""
    reachable = set()
    reachable.add(n)

    # We need to consider the cycle: 1 -> 2 -> 3 -> ... -> 9 -> 1
    # But wait, when we get to 9, we go to 10 -> 1, not 10 -> 2
    # So the cycle is 1 -> 2 -> 3 -> ... -> 9 -> 1

    # If we reach 1, we can reach all numbers from 1 to 9
    if 1 in reachable:
        for i in range(1, 10):
            reachable.add(i)

    return len(reachable)

