import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    likes = list(map(int, data[1:n+1]))

    # Count likes for each photo
    like_count = {}
    for photo in likes:
        like_count[photo] = like_count.get(photo, 0) + 1

    # Find the maximum number of likes
    max_likes = max(like_count.values())

    # For each photo, track when it reached the maximum count
    reach_time = {}
    for i, photo in enumerate(likes):
        if like_count[photo] == max_likes:
            reach_time[photo] = i + 1  # 1-indexed position

    # Among photos with max likes, find the one that reached it first
    winner = None
    for photo, time in reach_time.items():
        if winner is None or time < reach_time[winner]:
            winner = photo

    print(winner)

if __name__ == "__main__":
    solve()
"}

